"""PHPUnit templates used by generate_regression_tests.py: tenant isolation and financial integrity."""
from __future__ import annotations

import re
from typing import Any, Optional

from . import findings, phpscan, walker


def _php(value: Any) -> str:
    return "'" + str(value).replace("\\", "\\\\").replace("'", "\\'") + "'"


TENANT_HEAD = """<?php

namespace Tests\\Feature;

use Illuminate\\Foundation\\Testing\\RefreshDatabase;
use Tests\\TestCase;

/**
 * Generated by prodready %(version)s. Creates two tenants with one user each, then tries to reach the second
 * tenant's data as the first, through the model and through show routes. Run it before the fix (it must fail
 * where a finding exists) and after it (it must pass).
 */
class ProdreadyTenantIsolationTest extends TestCase
{
    use RefreshDatabase;

%(body)s}
"""

TENANT_TEST = """    public function test_%(slug)s_never_crosses_tenants(): void
    {
        $class = '\\\\App\\\\Models\\\\' . %(model)s;
        if (! class_exists($class) || ! method_exists($class, 'factory') || ! method_exists(\\App\\Models\\User::class, 'factory')) {
            $this->markTestSkipped('needs model factories for User and ' . %(model)s);
        }

        // Two tenants, one user each. Adjust the attribute names if your users or factories differ.
        $a = \\App\\Models\\User::factory()->create([%(col)s => 1]);
        $b = \\App\\Models\\User::factory()->create([%(col)s => 2]);
        $this->actingAs($b);
        $theirs = $class::factory()->create([%(col)s => 2]);
        $this->actingAs($a);
        $mine = $class::factory()->create([%(col)s => 1]);

        $seen = $class::query()->get()->map->getKey()->all();
        $this->assertContains($mine->getKey(), $seen);
        $this->assertNotContains($theirs->getKey(), $seen, 'a query as tenant A returned a row of tenant B');
        $this->assertNull($class::find($theirs->getKey()), 'find() as tenant A returned a row of tenant B');%(http)s
    }
"""

TENANT_HTTP = """
        $uri = preg_replace('/\\{[^}]+\\}/', (string) $theirs->getKey(), %s, 1);
        $this->assertContains($this->json('GET', $uri)->getStatusCode(), [403, 404], 'tenant A reached a record of tenant B through ' . $uri);"""

MONEY_HEAD = """<?php

namespace Tests\\Feature;

use Illuminate\\Foundation\\Testing\\RefreshDatabase;
use Tests\\TestCase;

/**
 * Generated by prodready %(version)s. Sends the same money request twice for an account that can afford it
 * once, then checks that no balance went negative and, for transfers, that the total money did not change.
 * The payload keys are a guess from common names; adjust them to your validation rules.
 */
class ProdreadyFinancialIntegrityTest extends TestCase
{
    use RefreshDatabase;

%(body)s}
"""

MONEY_TEST = """    public function test_%(i)d_%(slug)s_survives_a_repeat_and_an_overdraft(): void
    {
        $class = '\\\\App\\\\Models\\\\' . %(wallet)s;
        if (! class_exists($class) || ! method_exists($class, 'factory') || ! method_exists(\\App\\Models\\User::class, 'factory')) {
            $this->markTestSkipped('needs model factories for User and ' . %(wallet)s);
        }

        $user = \\App\\Models\\User::factory()->create();
        $other = \\App\\Models\\User::factory()->create();
        // Arrange: the sender has exactly 10, the receiver 0. Adjust the owner column if yours is not user_id.
        $mine = $class::factory()->create(['user_id' => $user->id, %(field)s => 10]);
        $theirs = $class::factory()->create(['user_id' => $other->id, %(field)s => 0]);
        $total = (float) $class::query()->sum(%(field)s);
        $payload = ['amount' => 10, 'to' => $theirs->getKey(), 'user_id' => $other->id, 'idempotency_key' => (string) \\Illuminate\\Support\\Str::uuid()];

        $this->actingAs($user);
        $this->json('POST', %(uri)s, $payload);
        $this->json('POST', %(uri)s, $payload); // the same request again: a retry or a double click

        $this->assertSame(0, $class::query()->where(%(field)s, '<', 0)->count(), 'a balance went negative (double spend)');%(cons)s
    }
"""

CONSERVED = "\n        $this->assertEqualsWithDelta($total, (float) $class::query()->sum(%s), 0.001, 'money was created or destroyed');"


def tenant_php(project: walker.Project) -> Optional[str]:
    import scan_tenancy
    inv = scan_tenancy.scan(project.root, None, project).inventory.get("tenancy") or {}
    tables = [t for t in inv.get("tables", []) if t.get("model")]
    if not tables:
        return None
    routes = phpscan.route_inventory(project)
    body = []
    for t in tables:
        model, col = t["model"], t["column"]
        http = ""
        for r in routes:
            if r["method"] != "GET" or r["uri"].count("{") != 1 or not r["controller"]:
                continue
            cf = phpscan.controller_file(project, r["controller"])
            m = next((x for x in cf.methods() if x["name"] == r["action"]), None) if cf else None
            if m and re.search(r"\b%s\s+\$" % re.escape(model), m["params"]):
                http += "\n        $this->actingAs($a);" + TENANT_HTTP % _php(r["uri"])
                break
        body.append(TENANT_TEST % {"slug": re.sub(r"\W+", "_", model.lower()), "model": _php(model), "col": _php(col), "http": http})
    return TENANT_HEAD % {"version": findings.__version__, "body": "\n".join(body)}


def financial_php(project: walker.Project) -> Optional[str]:
    models = phpscan.model_class_names(project)
    wallet = next((n for n, pf in models.items() if "balance" in pf.code or "credits" in pf.code), None)
    if not wallet:
        return None
    field = "balance" if "balance" in models[wallet].code else "credits"
    rows = []
    for r in phpscan.route_inventory(project):
        if r["method"] == "POST" and re.search(r"(?i)transfer|withdraw|payout|pay\b|send|spend|redeem|purchase|checkout", r["uri"]) and not re.search(r"(?i)webhook", r["uri"]):
            rows.append((r["uri"], bool(re.search(r"(?i)transfer|send|move", r["uri"]))))
    if not rows:
        return None
    body = []
    for i, (uri, conserved) in enumerate(rows[:6], 1):
        body.append(MONEY_TEST % {"i": i, "slug": re.sub(r"\W+", "_", uri.lower()).strip("_"), "wallet": _php(wallet), "field": _php(field), "uri": _php(uri), "cons": CONSERVED % _php(field) if conserved else ""})
    return MONEY_HEAD % {"version": findings.__version__, "body": "\n".join(body)}
